(() => {
'use strict';
const C=window.PORTFOLIO,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const saved=(k,d)=>{try{return localStorage.getItem('kw-'+k)||d;}catch{return d;}};
const save=(k,v)=>{try{localStorage.setItem('kw-'+k,v);}catch{}};
let lang=saved('language','zh-CN');if(!TRANSLATIONS[lang])lang='zh-CN';
let theme=saved('theme','day');if(!['day','night'].includes(theme))theme='day';
let fontSize=saved('font-size','medium');if(!['small','medium','large'].includes(fontSize))fontSize='medium';
const t=k=>TRANSLATIONS[lang][k]||k;
const local=v=>v&&typeof v==='object'&&!Array.isArray(v)?v[lang]||v['zh-CN']||v.en||'':v||'';
const url=v=>{try{const u=new URL(v,location.href);return v&&['https:','http:','file:'].includes(u.protocol)?u.href:'';}catch{return '';}};
const apps=[{id:'about',icon:'676(32x32).png'},{id:'research',icon:'318(48x48).png'},{id:'visual',icon:'680(32x32).png'},{id:'resume',icon:'327(32x32).png'},{id:'contact',icon:'mail.png'},{id:'radio',icon:'111(48x48).png'}];
const icon=a=>`<img class="xp-icon" src="assets/xp/${a.icon}" alt="">`;
const windows=new Map();let authenticated=false,powered=true,booting=false,active=null,z=40,bootTimer,toastTimer,audioCtx;
let sound=saved('sound','on')!=='off';
const music=new Audio();music.preload='metadata';const storedVolume=Number(saved('volume','0.45'));music.volume=Number.isFinite(storedVolume)?Math.max(0,Math.min(1,storedVolume)):.45;music.loop=true;
const tracks=C.music?.tracks||[{title:'Ditto (治愈bgm)',artist:'康河好声音',src:'assets/audio/ditto.mp3'}];
let trackIndex=0,playerMenu=false,audioError=false,loadingAudio=false;
function setTrack(i){trackIndex=(i+tracks.length)%tracks.length;music.src=url(tracks[trackIndex].src);audioError=false;loadingAudio=false;}
if(tracks.length)setTrack(0);
function preferenceMarkup(){return `<button data-theme data-label="${theme==='day'?'night':'day'}" title="${t(theme==='day'?'night':'day')}">${theme==='day'?'☾':'☀'}</button><select data-language aria-label="${t('language')}"><option value="zh-CN" ${lang==='zh-CN'?'selected':''}>简</option><option value="zh-TW" ${lang==='zh-TW'?'selected':''}>繁</option><option value="en" ${lang==='en'?'selected':''}>EN</option></select><select data-font-size aria-label="${t('fontSize')}" title="${t('fontSize')}">${['small','medium','large'].map(size=>`<option value="${size}" ${fontSize===size?'selected':''}>${t(size)}</option>`).join('')}</select><button data-sound title="${t(sound?'soundOn':'soundOff')}" aria-label="${t(sound?'soundOn':'soundOff')}"><img src="assets/icons/speaker-${sound?'high':'slash'}.svg" alt=""></button>`;}
function updatePreferences(){document.body.dataset.theme=theme;document.body.dataset.fontSize=fontSize;$('#outerPreferences').innerHTML=preferenceMarkup();$('#trayPreferences').innerHTML=preferenceMarkup();}
function translateStatic(){document.documentElement.lang=lang;document.title=`${C.name} · Windows XP`;$('[name="description"]').content=`${C.name} · ${t('copyright')}`;$$('[data-text]').forEach(e=>e.textContent=t(e.dataset.text));$$('[data-label]').forEach(e=>{e.setAttribute('aria-label',t(e.dataset.label));e.title=t(e.dataset.label);});$('#password').placeholder=t('password');$('#passwordHint').textContent=`${t('hint')}: ${C.password}`;$('#accountName').textContent=C.name;$('#loginUserLabel').textContent=C.name;$('.start-user b').textContent=C.name;$('.start-user .avatar').textContent=C.name;$('.start-button em').textContent=t('start');$('#lockButton').innerHTML=`<img src="assets/icons/power.svg" alt=""> ${t('lock')}`;$('#showDesktop').setAttribute('aria-label',t('desktop'));$('#powerButton').setAttribute('aria-label',t(powered?'shutdown':'powerOn'));$('#contrastToggle').setAttribute('aria-label',t('scan'));$('#brightnessToggle').setAttribute('aria-label',t('brightness'));$('#contrastToggle').title=t('scan');$('#brightnessToggle').title=t('brightness');$('.desktop-icons').setAttribute('aria-label',t('desktop'));$('.computer').setAttribute('aria-label',`${C.name} ${t('about')}`);$('.desktop-icons').innerHTML=apps.map(a=>`<button class="desktop-icon" data-open="${a.id}" title="${t(a.id)}">${icon(a)}<span>${t(a.id)}</span></button>`).join('');$('#startApps').innerHTML=apps.map(a=>`<button data-open="${a.id}">${icon(a)}<span>${t(a.id)}</span></button>`).join('');updatePreferences();updateClock();renderTasks();}
function setLanguage(value){lang=value;save('language',lang);translateStatic();windows.forEach((w,id)=>{updateWindowChrome(w);renderWindow(id);});if($('#loginError').textContent)$('#loginError').textContent=t('wrong');}
function updateClock(){const n=new Date();$('#clock').textContent=n.toLocaleTimeString(lang,{hour:'2-digit',minute:'2-digit',hour12:false});$('#clock').dateTime=n.toISOString();$('#clock').title=n.toLocaleDateString(lang);}
function notify(s){$('#toast').textContent=s;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2200);}
function audio(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();return audioCtx;}
function tone(f,d=.08,v=.018,offset=0){try{const ctx=audio(),o=ctx.createOscillator(),g=ctx.createGain(),at=ctx.currentTime+offset;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,at);g.gain.linearRampToValueAtTime(v,at+.025);g.gain.exponentialRampToValueAtTime(.0001,at+d);o.connect(g);g.connect(ctx.destination);o.start(at);o.stop(at+d+.02);}catch{}}
function clickSound(){if(sound)tone(880,.045,.008);}
// Original soft, layered startup chime inspired by early-2000s desktop sounds.
function startupSound(){if(!sound)return;[[392,0],[523.25,.15],[659.25,.34],[783.99,.61],[587.33,.9],[523.25,1.18]].forEach(([f,offset])=>{tone(f,1.75,.035,offset);tone(f/2,2,.014,offset);});}
function stopSystemAudio(){if(audioCtx)audioCtx.suspend().catch(()=>{});}
function closeStart(){$('#startMenu').hidden=true;$('#startButton').setAttribute('aria-expanded','false');}
function lock(){clearTimeout(bootTimer);booting=false;authenticated=false;$('#bootLayer').hidden=true;$('#loginLayer').hidden=false;$('#desktop').inert=true;$('#password').value='';$('#password').removeAttribute('aria-invalid');$('#loginError').textContent='';music.pause();stopSystemAudio();closeStart();$('#password').focus();}
function togglePower(){if(powered){lock();powered=false;$('#offLayer').hidden=false;$('#loginLayer').inert=true;}else{powered=true;$('#offLayer').hidden=true;$('#loginLayer').inert=false;$('#screen').classList.remove('starting');requestAnimationFrame(()=>$('#screen').classList.add('starting'));$('#password').focus();}$('.computer').classList.toggle('is-off',!powered);$('#powerButton').setAttribute('aria-label',t(powered?'shutdown':'powerOn'));}
$('#loginForm').addEventListener('submit',e=>{e.preventDefault();if(booting||!powered)return;if($('#password').value!==String(C.password)){$('#loginError').textContent=t('wrong');$('#password').setAttribute('aria-invalid','true');$('#loginForm').classList.remove('shake');requestAnimationFrame(()=>$('#loginForm').classList.add('shake'));if(sound)tone(220,.12);return;}if(sound)audio();$('#password').removeAttribute('aria-invalid');$('#loginError').textContent='';booting=true;$('#loginLayer').hidden=true;$('#bootLayer').hidden=false;bootTimer=setTimeout(()=>{booting=false;authenticated=true;$('#bootLayer').hidden=true;$('#desktop').inert=false;$('.desktop-icon').focus();startupSound();},matchMedia('(prefers-reduced-motion:reduce)').matches?150:2400);});
$('#fillPassword').addEventListener('click',()=>{$('#password').value=C.password;$('#password').focus();$('#loginError').textContent='';});
$('#startButton').addEventListener('click',()=>{$('#startMenu').hidden=!$('#startMenu').hidden;$('#startButton').setAttribute('aria-expanded',String(!$('#startMenu').hidden));clickSound();});
$('#screen').addEventListener('pointerdown',e=>{if(!e.target.closest('.start-menu,.start-button'))closeStart();});
$('#lockButton').addEventListener('click',lock);$('#powerButton').addEventListener('click',togglePower);$('#loginPower').addEventListener('click',togglePower);$('#turnOn').addEventListener('click',togglePower);
$('#contrastToggle').addEventListener('click',()=>$('#screen').classList.toggle('no-scan'));
$('#brightnessToggle').addEventListener('click',()=>$('#screen').classList.toggle('dim'));
function renderTasks(){$('#tasks').innerHTML=[...windows].map(([id,w])=>`<button class="task ${active===id&&!w.hidden?'active':''}" data-task="${id}" aria-label="${t(id)}">${icon(apps.find(a=>a.id===id))}<span>${t(id)}</span></button>`).join('');}
function focusWindow(id){const w=windows.get(id);if(!w)return;w.hidden=false;w.style.zIndex=++z;active=id;windows.forEach((w,key)=>w.classList.toggle('inactive',key!==id));renderTasks();}
function selectTop(){const visible=[...windows].filter(([,w])=>!w.hidden).sort((a,b)=>Number(b[1].style.zIndex)-Number(a[1].style.zIndex));active=visible[0]?.[0]||null;windows.forEach((w,id)=>w.classList.toggle('inactive',id!==active));renderTasks();}
function closeWindow(id){if(id==='radio')music.pause();windows.get(id)?.remove();windows.delete(id);selectTop();$(`.desktop-icon[data-open="${id}"]`)?.focus();}
function updateWindowChrome(w){const id=w.dataset.app,a=apps.find(a=>a.id===id);w.setAttribute('aria-label',t(id));w.querySelector('.titlebar').innerHTML=`<span class="window-title">${icon(a)}${t(id)}</span><div class="window-controls"><button data-window-action="minimize" aria-label="${t('minimize')} ${t(id)}">_</button><button data-window-action="maximize" aria-label="${t(w.classList.contains('maximized')?'restore':'maximize')} ${t(id)}">${w.classList.contains('maximized')?'❐':'□'}</button><button data-window-action="close" aria-label="${t('close')} ${t(id)}">×</button></div>`;w.querySelector('.window-menu').innerHTML=`<span>${t('file')}(F)</span><span>${t('view')}(V)</span><span>${C.name}</span>`;w.querySelector('.window-status').innerHTML=`<span>${t(id)}</span><span>▧</span>`;}
function renderWindow(id){const w=windows.get(id);if(!w)return;w.classList.toggle('folder-window',['research','visual'].includes(id));w.querySelector('.window-content').innerHTML=['research','visual'].includes(id)?renderFolder(id,w.dataset.project):renderApp(id);if(id==='radio')updatePlayer();}
function openApp(id){if(!authenticated||!powered)return;closeStart();clickSound();if(windows.has(id)){focusWindow(id);return;}const w=document.createElement('section');w.className='app-window'+(id==='radio'?' ipod-window':'');w.dataset.app=id;w.setAttribute('role','dialog');w.innerHTML='<header class="titlebar"></header><div class="window-menu"></div><div class="window-content" tabindex="0"></div><footer class="window-status"></footer>';const offset=windows.size%3;w.style.top=(3+offset*2)+'%';w.style.left=(19+offset)+'%';$('#windows').append(w);windows.set(id,w);updateWindowChrome(w);renderWindow(id);w.addEventListener('pointerdown',()=>{if(active!==id)focusWindow(id);});w.querySelector('.titlebar').addEventListener('dblclick',e=>{if(!e.target.closest('button'))maximize(w);});installDrag(w);focusWindow(id);w.querySelector('.window-content').focus();}
function maximize(w){w.classList.toggle('maximized');updateWindowChrome(w);}
function installDrag(w){const bar=w.querySelector('.titlebar');bar.addEventListener('pointerdown',e=>{if(e.target.closest('button')||w.classList.contains('maximized')||innerWidth<768)return;const area=$('#windows').getBoundingClientRect(),r=w.getBoundingClientRect();const sx=e.clientX,sy=e.clientY,ox=r.left-area.left,oy=r.top-area.top;bar.setPointerCapture(e.pointerId);const move=ev=>{w.style.left=Math.max(0,Math.min(area.width-r.width,ox+ev.clientX-sx))+'px';w.style.top=Math.max(0,Math.min(area.height-r.height,oy+ev.clientY-sy))+'px';};const end=()=>{bar.removeEventListener('pointermove',move);bar.removeEventListener('pointerup',end);bar.removeEventListener('pointercancel',end);};bar.addEventListener('pointermove',move);bar.addEventListener('pointerup',end);bar.addEventListener('pointercancel',end);});}
$('#showDesktop').addEventListener('click',()=>{const hide=[...windows.values()].some(w=>!w.hidden);windows.forEach(w=>w.hidden=hide);selectTop();});
document.addEventListener('click',e=>{const el=e.target.closest('button,a');if(!el)return;if(el.hasAttribute('data-theme')){theme=theme==='day'?'night':'day';save('theme',theme);updatePreferences();return;}if(el.hasAttribute('data-sound')){sound=!sound;save('sound',sound?'on':'off');music.muted=!sound;if(!sound)stopSystemAudio();updatePreferences();return;}if(el.dataset.open){openApp(el.dataset.open);return;}if(el.dataset.task){const id=el.dataset.task,w=windows.get(id);if(active===id&&!w.hidden){w.hidden=true;selectTop();}else focusWindow(id);return;}const w=el.closest('.app-window');if(el.dataset.windowAction){const id=w.dataset.app;if(el.dataset.windowAction==='close')closeWindow(id);else if(el.dataset.windowAction==='minimize'){w.hidden=true;selectTop();}else maximize(w);return;}if(el.hasAttribute('data-filter')){w.dataset.filter=el.dataset.filter;delete w.dataset.project;renderWindow(w.dataset.app);return;}if(el.dataset.project){const scroll=w.querySelector('.folder-sidebar')?.scrollTop||0;w.dataset.project=el.dataset.project;renderWindow(w.dataset.app);const sidebar=w.querySelector('.folder-sidebar');if(sidebar){sidebar.scrollTop=scroll;sidebar.querySelector('[aria-current="page"]')?.focus({preventScroll:true});}return;}if(el.hasAttribute('data-back')){delete w.dataset.project;renderWindow(w.dataset.app);return;}if(el.dataset.copy){copyText(el.dataset.copy);return;}if(el.hasAttribute('data-player-play'))toggleMusic();if(el.hasAttribute('data-player-menu')){playerMenu=!playerMenu;renderWindow('radio');}if(el.hasAttribute('data-track')){const wasPlaying=!music.paused;setTrack(Number(el.dataset.track));playerMenu=false;renderWindow('radio');if(wasPlaying)playMusic();}if(el.hasAttribute('data-player-prev')){music.currentTime=0;if(tracks.length>1)changeTrack(-1);updatePlayer();}if(el.hasAttribute('data-player-next')){if(tracks.length>1)changeTrack(1);else{music.currentTime=0;updatePlayer();}}if(el.hasAttribute('data-player-repeat')){music.loop=!music.loop;updatePlayer();}if(el.hasAttribute('data-player-retry')){music.load();playMusic();}});
document.addEventListener('change',e=>{if(e.target.matches('[data-language]'))setLanguage(e.target.value);if(e.target.matches('[data-font-size]')){fontSize=e.target.value;save('font-size',fontSize);document.body.dataset.fontSize=fontSize;$$('[data-font-size]').forEach(s=>s.value=fontSize);}});
document.addEventListener('input',e=>{if(e.target.id==='musicVolume'){music.volume=Number(e.target.value);save('volume',String(music.volume));}if(e.target.id==='musicSeek'&&Number.isFinite(music.duration))music.currentTime=Number(e.target.value);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#startMenu').hidden)closeStart();else if(active)closeWindow(active);}if(e.altKey&&e.key.toLowerCase()==='m'&&active){e.preventDefault();windows.get(active).hidden=true;selectTop();}if(e.code==='Space'&&active==='radio'&&!e.target.closest('input,button,select,a')){e.preventDefault();toggleMusic();}});
window.addEventListener('resize',()=>{windows.forEach(w=>{if(!w.classList.contains('maximized')&&innerWidth>=768){const a=$('#windows').getBoundingClientRect(),r=w.getBoundingClientRect();w.style.left=Math.max(0,Math.min(r.left-a.left,a.width-r.width))+'px';w.style.top=Math.max(0,Math.min(r.top-a.top,a.height-r.height))+'px';}});});
function contactRow(code,key,value,protocol){const valid=protocol==='mailto'?/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value):/^\+?[\d\s()-]{6,}$/.test(value);return `<div class="contact-row"><div class="contact-code">${code}</div><div><small>${t(key)}</small><b>${value?valid?`<a href="${protocol}:${esc(protocol==='tel'?value.replace(/[\s()-]/g,''):value)}">${esc(value)}</a>`:esc(value):`<span class="muted">${code==='HK'?'+852 ':code==='CN'?'+86 ':''}${t('pending')}</span>`}</b></div>${value?`<button class="retro-button" data-copy="${esc(value)}">${t('copy')}</button>`:''}</div>`;}
async function copyText(v){try{await navigator.clipboard.writeText(v);notify(t('copied'));}catch{notify(t('copyError'));}}
function renderApp(id,filter){if(id==='radio')return renderIPod();if(id==='research'||id==='visual')return renderFolder(id,filter);if(id==='about')return `<div class="page-content"><div class="welcome-art"><img class="about-computer" src="assets/xp/676(32x32).png" alt=""><div><h2>${esc(C.name)}</h2><p>${t('copyright')}</p></div></div>${local(C.introduction)?`<p>${esc(local(C.introduction))}</p>`:''}${C.location?`<p>${esc(local(C.location))}</p>`:''}<div class="about-shortcuts">${apps.filter(a=>['research','visual','resume','contact'].includes(a.id)).map(a=>`<button data-open="${a.id}">${icon(a)}<span>${t(a.id)}</span></button>`).join('')}</div></div>`;
if(id==='resume')return `<div class="page-content"><h2>${t('resume')}</h2><h3>${t('experience')}</h3>${C.experience.length?`<div class="timeline">${C.experience.map(x=>`<article><small>${esc(local(x.period))}</small><h3>${esc(local(x.title))}</h3><p>${esc(local(x.description))}</p></article>`).join('')}</div>`:`<p class="muted">${t('pending')}</p>`}<h3>${t('skills')}</h3>${C.skills.length?`<div class="skill-list">${C.skills.map(v=>`<span>${esc(local(v))}</span>`).join('')}</div>`:`<p class="muted">${t('pending')}</p>`}${url(C.resumeUrl)?`<a class="retro-button" href="${esc(url(C.resumeUrl))}" target="_blank" rel="noopener">${t('resumeFile')} ↗</a>`:''}</div>`;
if(id==='contact')return `<div class="page-content"><h2>${t('contact')}</h2>${contactRow('HK','hk',C.contacts.hongKong,'tel')}${contactRow('CN','cn',C.contacts.mainland,'tel')}${contactRow('@','email',C.contacts.email,'mailto')}</div>`;return '';}
function cover(p){if(url(p.image))return `<div class="project-cover"><img src="${esc(url(p.image))}" alt="${esc(local(p.title))}" style="width:100%;height:100%;object-fit:cover"></div>`;return `<div class="project-cover simple-cover ${esc(p.category)}"><img src="assets/xp/${p.category==='research'?'318(48x48).png':'680(32x32).png'}" alt=""></div>`;}
function renderFolder(category,selectedId){
 const projects=C.projects.filter(p=>p.category===category),selected=projects.find(p=>p.id===selectedId)||projects[0];
 const groups=[...new Map(projects.map(p=>[JSON.stringify(p.type),p.type])).entries()];
 const w=windows.get(category);if(w&&selected)w.dataset.project=selected.id;
 return `<div class="folder-layout"><nav class="folder-sidebar" aria-label="${t(category)}"><div class="folder-sidebar-heading"><img src="assets/xp/318(48x48).png" alt=""><strong>${t(category)}</strong><small>${projects.length} ${t('files')}</small></div>${groups.map(([key,type])=>`<section class="folder-group"><h3>${esc(local(type))}</h3><div>${projects.filter(p=>JSON.stringify(p.type)===key).map(p=>`<button class="folder-item" data-project="${esc(p.id)}" ${selected?.id===p.id?'aria-current="page"':''}><img src="assets/xp/327(32x32).png" alt=""><span>${esc(local(p.title))}</span></button>`).join('')}</div></section>`).join('')}</nav><article class="folder-preview" aria-label="${selected?esc(local(selected.title)):t(category)}" tabindex="0">${selected?renderProject(selected.id):`<div class="empty-filter">${t('empty')}</div>`}</article></div>`;
}
function renderProject(id){const p=C.projects.find(x=>x.id===id);if(!p)return '';return `<div class="page-content project-detail"><div class="eyebrow">${esc(local(p.type))}${p.demo?' / '+t('sample'):''}</div><h2>${esc(local(p.title))}</h2>${local(p.summary)?`<p>${esc(local(p.summary))}</p>`:''}${(p.process||[]).length?`<h3>${t('process')}</h3><ol class="process">${p.process.map(s=>`<li>${esc(local(s))}</li>`).join('')}</ol>`:''}${local(p.outcome)?`<h3>${t('outcome')}</h3><p>${esc(local(p.outcome))}</p>`:''}${url(p.image)?cover(p):''}${url(p.url)?`<a class="retro-button" href="${esc(url(p.url))}" target="_blank" rel="noopener">${t('openWork')} ↗</a>`:`<div class="text-note">${t('noFile')}</div>`}</div>`;}
function time(s){if(!Number.isFinite(s))return '0:00';return Math.floor(s/60)+':'+String(Math.floor(s%60)).padStart(2,'0');}
function renderIPod(){const track=tracks[trackIndex];if(!track)return `<div class="empty-filter">${t('empty')}</div>`;return `<div class="ipod-stage"><div class="ipod"><div class="hold-switch"></div><div class="ipod-display"><header><span>${playerMenu?t('music'):t('nowPlaying')}</span><span class="battery" aria-hidden="true"></span></header>${playerMenu?`<div class="ipod-song-list">${tracks.map((track,i)=>`<button data-track="${i}" class="${trackIndex===i?'selected':''}"><span>${esc(local(track.title))}</span><b>›</b></button>`).join('')}</div>`:`<div class="ipod-track"><div class="ipod-track-number">${trackIndex+1} / ${tracks.length}<button data-player-repeat aria-label="${t('repeat')}" title="${t('repeat')}">↻</button></div><div class="ipod-song"><div class="album-art">${url(track.cover)?`<img src="${esc(url(track.cover))}" alt="${esc(local(track.title))}">`:'<span>♫</span>'}</div><div><strong>${esc(local(track.title))}</strong><span>${esc(local(track.artist))}</span></div></div><div id="playerState" role="status"></div><input id="musicSeek" type="range" min="0" max="${music.duration||1}" step=".1" value="${music.currentTime}" aria-label="${t('seek')}"><div class="ipod-time"><span id="elapsedTime">${time(music.currentTime)}</span><span id="remainingTime">-${time(music.duration-music.currentTime)}</span></div></div>`}</div><div class="click-wheel"><button class="wheel-menu" data-player-menu aria-label="${t('menu')}">MENU</button><button class="wheel-prev" data-player-prev aria-label="${t('previous')}">Ⅰ◀◀</button><button class="wheel-next" data-player-next aria-label="${t('next')}">▶▶Ⅰ</button><button class="wheel-play" data-player-play aria-label="${t(music.paused?'play':'pause')}">▶Ⅱ</button><button class="wheel-center" data-player-play aria-label="${t(music.paused?'play':'pause')}"></button></div><div class="ipod-signature">iPod</div></div><div class="ipod-volume"><label for="musicVolume">${t('volume')}</label><input id="musicVolume" type="range" min="0" max="1" step=".01" value="${music.volume}" aria-label="${t('volume')}"></div></div>`;}
function updatePlayer(){const w=windows.get('radio');if(!w)return;w.querySelectorAll('[data-player-play]').forEach(b=>b.setAttribute('aria-label',t(music.paused?'play':'pause')));const state=w.querySelector('#playerState');if(state)state.innerHTML=audioError?`${t('audioError')} <button data-player-retry>${t('retry')}</button>`:loadingAudio?t('loading'):music.paused?t('paused'):'▶';const seek=w.querySelector('#musicSeek');if(seek){seek.max=Number.isFinite(music.duration)?music.duration:1;seek.disabled=!Number.isFinite(music.duration);if(document.activeElement!==seek)seek.value=music.currentTime;}const elapsed=w.querySelector('#elapsedTime'),remaining=w.querySelector('#remainingTime');if(elapsed)elapsed.textContent=time(music.currentTime);if(remaining)remaining.textContent='-'+time(music.duration-music.currentTime);const repeat=w.querySelector('[data-player-repeat]');if(repeat){repeat.setAttribute('aria-pressed',String(music.loop));repeat.style.opacity=music.loop?'1':'.35';}}
async function playMusic(){audioError=false;loadingAudio=true;sound=true;music.muted=false;save('sound','on');updatePreferences();updatePlayer();try{await music.play();loadingAudio=false;}catch{loadingAudio=false;audioError=true;}updatePlayer();}
function toggleMusic(){if(music.paused)playMusic();else music.pause();}
function changeTrack(d){const playing=!music.paused;setTrack(trackIndex+d);renderWindow('radio');if(playing)playMusic();}
['loadedmetadata','timeupdate','durationchange','pause','playing','ended','volumechange'].forEach(event=>music.addEventListener(event,()=>{if(event==='playing')loadingAudio=false;updatePlayer();}));
music.addEventListener('waiting',()=>{loadingAudio=true;updatePlayer();});music.addEventListener('canplay',()=>{loadingAudio=false;audioError=false;updatePlayer();});music.addEventListener('error',()=>{audioError=true;loadingAudio=false;updatePlayer();});
window.addEventListener('pagehide',()=>{music.pause();stopSystemAudio();});
$('#year').textContent=new Date().getFullYear();translateStatic();setInterval(updateClock,30000);
})();
